pm.test(": Status code is 200", function () {
    pm.response.to.have.status(200);
});

const data = pm.response.json();

pm.test("Order status is ready_for_pickup", function () {
    pm.expect(data.status).to.eql("accepted");
});

pm.test("Timeline included", function () {
    pm.expect(data.timeline).to.be.an("array");
});

pm.test("Items included", function () {
    pm.expect(data.items).to.be.an("array");
});

pm.test("Customer filter: Status code is 200", function () {
    pm.response.to.have.status(200);
});

const data = pm.response.json();

data.orders.forEach(order => {
    pm.test("Order matches customer filter", function () {
        pm.expect(order.customerId)
            .to.eql(pm.environment.get("customerId"));
    });
});

pm.test("TC-200: Status code is 200", function () {
    pm.response.to.have.status(200);
});

const data = pm.response.json();

pm.test("Order ID is correct", function () {
    pm.expect(data.id).to.eql(pm.environment.get("orderId3"));
});

pm.test("Order is claimed", function () {
    pm.expect(data.status).to.eql("claimed");
});

pm.test("Rider is assigned", function () {
    pm.expect(data.riderId)
        .to.eql(pm.environment.get("riderId"));
});

pm.test("TC-205: Status code is 200", function () {
    pm.response.to.have.status(200);
});

const data = pm.response.json();

pm.test("Order is picked up", function () {
    pm.expect(data.status).to.eql("picked_up");
});

pm.test("Correct rider remains assigned", function () {
    pm.expect(data.riderId)
        .to.eql(pm.environment.get("riderId"));
});

pm.test("TC-208: Unauthorized rider rejected", function () {
    pm.expect([401, 403]).to.include(pm.response.code);
});

const data = pm.response.json();

pm.test("Permission error exists", function () {
    pm.expect(data.error).to.exist;
});
